CREATE TABLE IF NOT EXISTS drawing_symbol_signature_versions (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,approved_geometry_version_id TEXT NOT NULL,symbol_recognition_version_id TEXT NOT NULL,version_number INTEGER NOT NULL,input_fingerprint TEXT NOT NULL,output_fingerprint TEXT NOT NULL,engine_version TEXT NOT NULL,status TEXT NOT NULL,summary TEXT NOT NULL,approved_normalized_signature TEXT NOT NULL,approved_raw_signature TEXT NOT NULL,created_by TEXT NOT NULL,superseded_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS drawing_symbol_signature_version_idx ON drawing_symbol_signature_versions(document_id,version_number);
CREATE TABLE IF NOT EXISTS drawing_symbol_occurrence_match_candidates (id TEXT PRIMARY KEY,signature_version_id TEXT NOT NULL,approved_geometry_link_id TEXT NOT NULL,occurrence_id TEXT NOT NULL,page_number INTEGER NOT NULL,bounding_box TEXT NOT NULL,coordinates TEXT,similarity_score INTEGER NOT NULL,matching_basis TEXT NOT NULL,geometry_differences TEXT NOT NULL,confidence INTEGER NOT NULL,review_status TEXT NOT NULL DEFAULT 'Needs Review',normalized_signature TEXT NOT NULL,raw_signature TEXT NOT NULL,reviewed_by TEXT,reviewed_at TEXT,review_reason TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS drawing_symbol_occurrence_match_idx ON drawing_symbol_occurrence_match_candidates(signature_version_id,occurrence_id);
CREATE TABLE IF NOT EXISTS drawing_symbol_occurrence_match_events (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,signature_version_id TEXT NOT NULL,candidate_id TEXT NOT NULL,action TEXT NOT NULL,previous_value TEXT NOT NULL,new_value TEXT NOT NULL,reason TEXT NOT NULL,actor_user_id TEXT NOT NULL,request_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS drawing_symbol_occurrence_match_event_idx ON drawing_symbol_occurrence_match_events(candidate_id,created_at);
